	addi x2, x2, SIG_STRIDE
    # Branchless mepc advance — reads bits[1:0] from *mepc using lhu.
    # lhu is used because mepc is only guaranteed 2-byte aligned.
    # advance = (((bits[1:0]+1) >> 2) + 1) << 1  =  4 if bits[1:0]==0b11, else 2.
